tool_input.content:
const fs = require('fs');
const html = fs.readFileSync(process.argv[2], 'utf8');
const m = html.match(/<script>([\s\S]*)<\/script>/);
const src = m[1];

function mkEl(){
  const el = {
    _html: '', style: { cssText: '' }, dataset: {}, value: '', textContent: '', scrollTop: 0,
    classList: { add(){}, remove(){} },
    getAttribute(){ return 'tip'; },
    setAttribute(){}, focus(){}, select(){}, appendChild(){},
    matches(){ return false; }, closest(){ return null; },
    querySelectorAll(){ return []; }, querySelector(){ return mkEl(); },
    addEventListener(){}, onclick: null, onchange: null, oninput: null, onkeydown: null,
    getBoundingClientRect(){ return { width: 100, height: 50 }; }
  };
  Object.defineProperty(el, 'innerHTML', { get(){ return el._html; }, set(v){ el._html = v; } });
  return el;
}
const docEl = mkEl();
docEl._html = src;
global.document = {
  documentElement: docEl,
  body: mkEl(),
  querySelector(){ return mkEl(); },
  querySelectorAll(){ return []; },
  createElement(){ return mkEl(); },
  addEventListener(){}
};
global.window = { innerWidth: 1200, innerHeight: 800, addEventListener(){} };

eval(src);

console.log(runTests());

console.log('\n--- benchmark determinism (seed 1337, 200 turns) ---');
const a = runBenchmark(1337, 200), b = runBenchmark(1337, 200);
console.log('hashA', stateHash(a), 'hashB', stateHash(b), stateHash(a) === stateHash(b) ? 'MATCH' : 'MISMATCH');
console.log('pop', a.colonists.length, 'tech', Object.keys(a.tech).length, 'bldgs', builtTiles(a).length, 'score', scoreOf(a).total);
console.log('morale', fmt(avgMorale(a)), 'food', fmt(a.res.food), 'water', fmt(a.res.water), 'scrip', fmt(a.res.scrip));

console.log('\n--- 60-turn greedy runs across seeds ---');
[1337, 7, 99, 2024, 555, 42].forEach(sd => {
  const s = runBenchmark(sd, 60);
  const w = winCheck(s);
  console.log('seed', sd, '| pop', s.colonists.length, '| mor', fmt(avgMorale(s)),
    '| food', fmt(s.res.food), '| wat', fmt(s.res.water), '| tech', Object.keys(s.tech).length,
    '| bld', builtTiles(s).length, '| starve', s.stats.starveTurns, '| thirst', s.stats.thirstTurns,
    '| WIN', w.win);
});

console.log('\n--- do-nothing runs (no policy) should fail ---');
[1337, 7].forEach(sd => {
  const s = newState(sd); s.auto = true; s.bench = true;
  for (let i = 0; i < 60; i++){ const r = runTurn(s); if (r === 'PAUSE'){ resolvePending(s, 0); runTurn(s); } }
  console.log('seed', sd, '| pop', s.colonists.length, '| mor', fmt(avgMorale(s)), '| WIN', winCheck(s).win);
});
